import React from 'react';
import { motion } from 'framer-motion';

interface GlassCardProps {
  children: React.ReactNode;
  className?: string;
  hoverEffect?: boolean;
  delay?: number;
}

export const GlassCard: React.FC<GlassCardProps> = ({ 
  children, 
  className = '', 
  hoverEffect = false,
  delay = 0 
}) => {
  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true }}
      transition={{ duration: 0.6, delay, ease: "easeOut" }}
      className={`
        relative overflow-hidden
        bg-glass backdrop-blur-xl 
        border border-glass-border 
        rounded-2xl
        transition-all duration-500
        ${hoverEffect ? 'hover:bg-glass-hover hover:border-secondary/30 hover:shadow-[0_0_30px_rgba(101,36,111,0.2)]' : ''}
        ${className}
      `}
    >
      {/* Subtle Gradient Noise Texture Overlay could go here */}
      <div className="relative z-10 h-full">
        {children}
      </div>

      {/* Decorative Gradient Blob */}
      {hoverEffect && (
        <div className="absolute -bottom-20 -right-20 w-40 h-40 bg-secondary/20 blur-[50px] rounded-full pointer-events-none transition-opacity duration-500 opacity-0 group-hover:opacity-100" />
      )}
    </motion.div>
  );
};

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Menu, X } from 'lucide-react';
import { NAV_ITEMS } from '../constants';

export const Navbar: React.FC = () => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <nav
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-500 ${
        isScrolled ? 'py-4' : 'py-8'
      }`}
    >
      <div className="max-w-7xl mx-auto px-6">
        <div 
          className={`
            flex items-center justify-between px-6 py-4 rounded-full
            transition-all duration-500
            ${isScrolled 
              ? 'bg-[#050205]/80 backdrop-blur-md border border-white/10 shadow-lg shadow-purple-900/10' 
              : 'bg-transparent border border-transparent'
            }
          `}
        >
          {/* Logo */}
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 rounded bg-gradient-to-br from-secondary to-primary flex items-center justify-center">
              <div className="w-3 h-3 bg-white rounded-full" />
            </div>
            <span className="text-2xl font-display font-bold tracking-tight text-white">
              Innervisio
            </span>
          </div>

          {/* Desktop Nav */}
          <div className="hidden md:flex items-center gap-8">
            {NAV_ITEMS.map((item) => (
              <a
                key={item.label}
                href={item.href}
                className="text-sm font-medium text-gray-300 hover:text-white transition-colors tracking-wide"
              >
                {item.label}
              </a>
            ))}
            <button className="px-5 py-2 rounded-full bg-white text-black font-semibold text-sm hover:bg-purple-100 transition-colors">
              Start Project
            </button>
          </div>

          {/* Mobile Toggle */}
          <button 
            className="md:hidden text-white"
            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
          >
            {mobileMenuOpen ? <X /> : <Menu />}
          </button>
        </div>
      </div>

      {/* Mobile Menu */}
      <AnimatePresence>
        {mobileMenuOpen && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            className="md:hidden bg-[#050205] border-b border-white/10 overflow-hidden"
          >
            <div className="flex flex-col p-6 gap-4">
              {NAV_ITEMS.map((item) => (
                <a
                  key={item.label}
                  href={item.href}
                  onClick={() => setMobileMenuOpen(false)}
                  className="text-lg font-display text-gray-300 hover:text-secondary transition-colors"
                >
                  {item.label}
                </a>
              ))}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </nav>
  );
};

