import React, { useState, useEffect } from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import { Navbar } from './components/Navbar';
import { Hero } from './components/Hero';
import { ServiceGrid } from './components/ServiceGrid';
import { PortfolioGallery } from './components/PortfolioGallery';
import { Footer } from './components/Footer';
import { HERO_SLIDES } from './constants';

function App() {
  const [currentSlide, setCurrentSlide] = useState(0);

  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentSlide((prev) => (prev + 1) % HERO_SLIDES.length);
    }, 10000);

    return () => clearInterval(timer);
  }, []);

  return (
    <div className="relative min-h-screen bg-background selection:bg-secondary selection:text-white overflow-x-hidden">

      {/* GLOBAL BACKGROUND LAYER */}
      {/* Extends 150vh to cover Hero and half of Services */}
      <div className="absolute top-0 left-0 w-full h-[160vh] z-0 overflow-hidden pointer-events-none">
        <AnimatePresence mode="popLayout">
          <motion.div
            key={currentSlide}
            initial={{ opacity: 0, scale: 1.1 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0 }}
            transition={{ duration: 1.5, ease: "easeInOut" }}
            className="absolute inset-0"
          >
            {/* Dark overlay for text contrast */}
            <div className="absolute inset-0 bg-black/50 z-10" /> 

            {/* Gradient Mask at the bottom to fade into body color */}
            <div className="absolute bottom-0 left-0 w-full h-[40vh] bg-gradient-to-b from-transparent to-[#050205] z-20" />

            <img 
              src={HERO_SLIDES[currentSlide].image} 
              alt="Hero Background" 
              className="w-full h-full object-cover"
            />
          </motion.div>
        </AnimatePresence>

        {/* Ambient Glows */}
        <div className="absolute top-0 left-0 w-[500px] h-[500px] bg-primary/20 blur-[120px] rounded-full z-10" />
      </div>

      <Navbar />

      <main className="relative z-10">
        {/* Pass state control to Hero for the text and dots */}
        <Hero currentSlide={currentSlide} setCurrentSlide={setCurrentSlide} />

        <ServiceGrid />

        <PortfolioGallery />

        {/* CTA Section */}
        <section className="py-32 px-6">
            <div className="max-w-5xl mx-auto text-center">
                <h2 className="text-5xl md:text-7xl font-display font-bold text-white mb-8 tracking-tighter">
                    Jste připraveni vizualizovat <br/> své další mistrovské dílo?
                </h2>
                <button className="px-10 py-5 bg-secondary hover:bg-[#7a2c85] text-white rounded-full text-lg font-semibold transition-all shadow-[0_0_40px_rgba(101,36,111,0.4)] hover:shadow-[0_0_60px_rgba(101,36,111,0.6)]">
                    Kontaktujte nás
                </button>
            </div>
        </section>
      </main>

      <Footer />
    </div>
  );
}

export default App;

