const GalleryItem: React.FC<{ project: ProjectItem; index: number }> = ({ project, index }) => {
  const [isHovered, setIsHovered] = useState(false);
  const [mousePos, setMousePos] = useState({ x: 0, y: 0 });
  const cardRef = useRef<HTMLDivElement>(null);

  const handleMouseMove = (e: MouseEvent<HTMLDivElement>) => {
    if (!cardRef.current) return;
    const rect = cardRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    setMousePos({ x, y });
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: 60 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true, margin: "-50px" }}
      transition={{ 
        ...springTransition,
        delay: index * 0.1 
      }}
      className="break-inside-avoid relative group cursor-pointer mb-8"
      style={{ perspective: '1200px' }}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
      onMouseMove={handleMouseMove}
    >
      <div className={`relative w-full ${project.heightClass}`} ref={cardRef}>
        <motion.div
          animate={{ rotateY: isHovered ? 180 : 0 }}
          transition={{ duration: 0.6, ease: [0.23, 1, 0.32, 1] }} 
          className="w-full h-full relative"
          style={{ transformStyle: 'preserve-3d' }}
        >
          {/* ==================== FRONT FACE ==================== */}
          <div 
            className="absolute inset-0 w-full h-full rounded-2xl overflow-hidden backface-hidden"
            style={{ backfaceVisibility: 'hidden', WebkitBackfaceVisibility: 'hidden' }}
          >
            {/* Image */}
            <div className="relative w-full h-full bg-gray-900">
              <motion.img 
                src={project.imageUrl} 
                alt={project.title}
                className="w-full h-full object-cover"
                transition={{ duration: 0.8 }}
              />
              <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/20 to-transparent opacity-80" />
            </div>

            {/* Front Static Content */}
            <div className="absolute bottom-0 left-0 w-full p-6 z-10">
                 <div className="flex justify-between items-end">
                    <div>
                        <span className="text-secondary text-xs font-bold tracking-widest uppercase mb-2 block">{project.category}</span>
                        <h3 className="text-xl md:text-2xl font-display font-bold text-white leading-tight">{project.title}</h3>
                    </div>
                    <div className="p-3 bg-white/5 backdrop-blur-md rounded-full border border-white/10 group-hover:bg-white/10 transition-colors">
                        <ArrowUpRight className="w-5 h-5 text-white" />
                    </div>
                 </div>
            </div>
          </div>

          {/* ==================== BACK FACE ==================== */}
          <div 
            className="absolute inset-0 w-full h-full rounded-2xl overflow-hidden bg-[#0a050a] border border-white/10 shadow-2xl"
            style={{ 
              transform: 'rotateY(180deg)', 
              backfaceVisibility: 'hidden', 
              WebkitBackfaceVisibility: 'hidden' 
            }}
          >
            {/* Elegant Grid Pattern */}
            <div 
              className="absolute inset-0 opacity-20"
              style={{
                backgroundImage: 'radial-gradient(circle, rgba(255,255,255,0.2) 1px, transparent 1px)',
                backgroundSize: '32px 32px',
              }}
            />

            {/* Subtle Spotlight Effect */}
            <div 
              className="absolute inset-0 pointer-events-none transition-opacity duration-500"
              style={{
                background: `radial-gradient(400px circle at ${mousePos.x}px ${mousePos.y}px, rgba(101, 36, 111, 0.15), transparent 100%)`,
                opacity: isHovered ? 1 : 0
              }}
            />

            {/* Back Content */}
            <div className="relative z-10 h-full p-8 flex flex-col">
              <div className="flex justify-between items-start mb-4">
                 <div className="p-2 bg-white/5 rounded-full border border-white/10">
                   <Tag className="w-4 h-4 text-secondary" />
                 </div>
                 <span className="text-xs uppercase tracking-widest text-gray-500 font-bold">{project.category}</span>
              </div>

              <div className="flex-grow flex flex-col justify-center gap-4">
                <h3 className="text-2xl md:text-3xl font-display font-bold text-white leading-tight">
                  {project.title}
                </h3>

                <div className="flex items-center gap-2 text-sm text-gray-400 mb-2">
                  <MapPin className="w-4 h-4 text-secondary" />
                  <span>{project.location}</span>
                </div>

                <div className="h-px w-12 bg-secondary/50 my-2" />

                <p className="text-gray-300 leading-relaxed text-sm">
                  {project.description}
                </p>
              </div>

              <div className="mt-auto pt-4">
                 <button className="w-full py-3 bg-white text-black font-semibold rounded-lg hover:bg-purple-100 transition-colors text-sm shadow-[0_0_20px_rgba(255,255,255,0.1)]">
                   Zobrazit studii
                 </button>
              </div>
            </div>
          </div>
        </motion.div>
      </div>
    </motion.div>
  );
};

